sql.if:
SELECT f.conf_name AS account, 'huawei' AS provider, COALESCE(NULLIF(f.conf_region, ''), f.region_name) AS region, AS bill_month, f.service_type_name AS product_main, f.resource_type_name AS product_sub, CAST(f.charging_mode AS CHAR) AS charging_mode_raw, CAST(NULL AS CHAR) AS resource_id, CAST(NULL AS CHAR) AS resource_name, f.trade_time AS trade_time, COALESCE(f.cash_amount, 0) + COALESCE(f.coupon_amount, 0) + COALESCE(f.credit_amount, 0) AS pay_amount, COALESCE(f.official_amount, 0) AS official_amount, COALESCE(f.consume_amount, 0) AS consume_amount, COALESCE(f.official_discount_amount, 0) AS discount_amount, COALESCE(f.cash_amount, 0) AS cash_pay, COALESCE(f.coupon_amount, 0) AS voucher_pay, COALESCE(f.credit_amount, 0) AS credit_pay, COALESCE(f.debt_amount, 0) AS debt_amount, COALESCE(f.erase_amount, 0) AS erase_amount, COALESCE(f.writeoff_amount, 0) AS writeoff_amount, 'FEE_RECORD' AS amount_source, f.pk AS src_pk FROM h_cloud_bills_fee_records f WHERE f.deleted = 0
AND >= #{c.startMonth}
AND <= #{c.endMonth}
AND f.conf_name IN #{acc}

UNION ALL
SELECT q.conf_name AS account, 'tencent' AS provider, COALESCE(NULLIF(q.conf_region, ''), q.region_name) AS region, AS bill_month, q.business_code_name AS product_main, q.product_code_name AS product_sub, q.pay_mode_name AS charging_mode_raw, q.resource_id AS resource_id, q.resource_name AS resource_name, q.pay_time AS trade_time, COALESCE(, 0) + COALESCE(, 0) + COALESCE(, 0) AS pay_amount, COALESCE(, 0) AS official_amount, COALESCE(, 0) AS consume_amount, GREATEST( COALESCE(, 0) - COALESCE(, 0), 0 ) AS discount_amount, COALESCE(, 0) AS cash_pay, COALESCE(, 0) AS voucher_pay, COALESCE(, 0) AS credit_pay, 0 AS debt_amount, 0 AS erase_amount, 0 AS writeoff_amount, 'RESOURCE_SUMMARY' AS amount_source, q.pk AS src_pk FROM q_cloud_bill_resource_summary q WHERE q.deleted = 0
AND >= #{c.startMonth}
AND <= #{c.endMonth}
AND q.conf_name IN #{acc}

mapper.select:
SELECT t.src_pk AS srcPk, t.account AS account, t.provider AS provider, t.region AS region, t.bill_month AS billMonth, t.product_main AS productMain, t.product_sub AS productSub, t.charging_mode_raw AS chargingModeRaw, t.resource_id AS resourceId, t.resource_name AS resourceName, t.trade_time AS tradeTime, t.pay_amount AS payAmount, t.official_amount AS officialAmount, t.consume_amount AS consumeAmount, t.discount_amount AS discountAmount, t.cash_pay AS cashPay, t.voucher_pay AS voucherPay, t.credit_pay AS creditPay, t.debt_amount AS debtAmount, t.erase_amount AS eraseAmount, t.writeoff_amount AS writeoffAmount, t.amount_source AS amountSource FROM (
) t
ORDER BY
t.official_amount t.bill_month t.trade_time t.pay_amount
ASC DESC
, t.src_pk DESC, t.provider ASC LIMIT #{limit} OFFSET #{offset}

SELECT c.name AS name, c.provider AS provider, c.region AS region FROM cloud_conf c WHERE 1 = 1
AND c.provider IN #{p}
AND c.name IN #{a}
ORDER BY c.pk
